<?php $owner=in_array('system.owner',$workflowPermissions,true);$canPageEdit=$owner||in_array('content.pages.edit',$workflowPermissions,true);$canPostEdit=$owner||in_array('content.posts.edit',$workflowPermissions,true);$canPageReview=$owner||in_array('content.pages.review',$workflowPermissions,true);$canPostReview=$owner||in_array('content.posts.review',$workflowPermissions,true);$canPagePublish=$owner||in_array('content.pages.publish',$workflowPermissions,true);$canPostPublish=$owner||in_array('content.posts.publish',$workflowPermissions,true); ?>
<section class="sensecms-access-shell">
    <?php $sectionHero=['overline'=>'CONTENT · EDITORIAL OPERATIONS','title'=>'Publication workflow','description'=>'A single accountable queue for multilingual pages and posts across every facility within your responsibility.','icon'=>'git-pull-request-arrow','status'=>(int)($workflowCounts['all']??0).' active items','status_detail'=>(int)($workflowCounts['in_review']??0).' awaiting review'];require __DIR__.'/console-section-hero.php'; ?>
    <div class="sensecms-workflow-summary"><?php foreach(['in_review'=>['scan-search','Awaiting review'],'changes_requested'=>['message-square-warning','Changes requested'],'approved'=>['badge-check','Approved'],'draft'=>['file-pen-line','Drafts']]as$key=>[$icon,$label]): ?><a href="/content/workflow?state=<?= $key ?>" class="sensecms-workflow-stat"><i><span data-lucide="<?= $icon ?>"></span></i><span><b><?= (int)($workflowCounts[$key]??0) ?></b><span><?= $label ?></span></span></a><?php endforeach; ?></div>
    <nav class="sensecms-access-tabs" aria-label="Workflow state"><?php foreach(['all'=>'Active queue','in_review'=>'Awaiting review','changes_requested'=>'Changes requested','approved'=>'Approved','draft'=>'Drafts']as$key=>$label): ?><a href="/content/workflow?state=<?= $key ?>" class="<?= $workflowState===$key?'is-active':'' ?>"><?= $label ?><b><?= $key==='all'?(int)$workflowCounts['all']:(int)$workflowCounts[$key] ?></b></a><?php endforeach; ?></nav>
    <section class="card sensecms-workflow-list"><?php foreach($workflowItems as$item):$type=(string)$item['entity_type'];$state=(string)$item['workflow_state'];$canEdit=$type==='page'?$canPageEdit:$canPostEdit;$canReview=$type==='page'?$canPageReview:$canPostReview;$canPublish=$type==='page'?$canPagePublish:$canPostPublish; ?><article class="sensecms-workflow-row" data-workflow-context><div class="sensecms-workflow-identity"><span class="sensecms-workflow-icon"><i data-lucide="<?= $type==='page'?'file-text':'newspaper' ?>"></i></span><span><strong><?= $escape($item['title']) ?></strong><small><?= $escape(ucfirst($type).' · '.$item['facility_name']) ?></small></span></div><div class="sensecms-workflow-detail"><span class="sensecms-workflow-state is-<?= $escape($state) ?>"><?= $escape(str_replace('_',' ',$state)) ?></span><small>Owner: <?= $escape($item['owner_name']) ?></small></div><div class="sensecms-workflow-detail"><b><?= $escape($item['assigned_name']) ?></b><small><?= $item['review_requested_at']?'Submitted '.date('M j · H:i',strtotime((string)$item['review_requested_at'])):'Updated '.date('M j · H:i',strtotime((string)$item['updated_at'])) ?></small></div><div class="sensecms-workflow-actions"><a href="/content/<?= $type==='page'?'pages':'posts' ?>/<?= (int)$item['id'] ?>/edit" title="Open editor"><i data-lucide="pencil"></i></a><?php if($canEdit&&in_array($state,['draft','changes_requested'],true)&&!in_array($item['status'],['published','scheduled','private'],true)): ?><button data-workflow-action="submit" data-workflow-type="<?= $type ?>" data-workflow-id="<?= (int)$item['id'] ?>" title="Submit for review"><i data-lucide="send-horizontal"></i></button><?php endif; ?><?php if($canEdit&&$state==='in_review'): ?><button data-workflow-action="withdraw" data-workflow-type="<?= $type ?>" data-workflow-id="<?= (int)$item['id'] ?>" title="Withdraw review request"><i data-lucide="undo-2"></i></button><?php endif; ?><?php if($canReview&&$state==='in_review'): ?><button data-workflow-action="approve" data-workflow-type="<?= $type ?>" data-workflow-id="<?= (int)$item['id'] ?>" title="Approve"><i data-lucide="check"></i></button><button data-workflow-action="request-changes" data-workflow-type="<?= $type ?>" data-workflow-id="<?= (int)$item['id'] ?>" title="Request changes"><i data-lucide="message-square-warning"></i></button><?php endif; ?><?php if($canPublish&&$state==='approved'&&$item['status']!=='published'): ?><button data-workflow-action="publish" data-workflow-type="<?= $type ?>" data-workflow-id="<?= (int)$item['id'] ?>" title="Publish"><i data-lucide="rocket"></i></button><?php endif; ?></div></article><?php endforeach; ?><?php if(!$workflowItems): ?><div class="sensecms-content-empty"><i data-lucide="badge-check"></i><strong>The queue is clear</strong><span>No content matches this workflow state inside your facility scope.</span></div><?php endif; ?></section>
</section>
